using System.Text;

namespace TutorFlow.Api.Tests.Dobles;

public sealed class EscritorSincronizado : TextWriter
{
    private readonly StringBuilder _texto = new();
    private readonly Lock _candado = new();

    public override Encoding Encoding => Encoding.UTF8;

    public override void Write(char valor)
    {
        lock (_candado)
        {
            _texto.Append(valor);
        }
    }

    public override void Write(string? valor)
    {
        lock (_candado)
        {
            _texto.Append(valor);
        }
    }

    public override string ToString()
    {
        lock (_candado)
        {
            return _texto.ToString();
        }
    }
}
E
for f in Infraestructura/AuditoriaCapacidadAjenaConsolaTests.cs Infraestructura/AuditoriaConsolaTests.cs Infraestructura/AuditoriaPrecioDesconocidoConsolaTests.cs Operacion/AuditoriaDetalleYArchivoApiTests.cs Operacion/AuditoriaEnmascaradoApiTests.cs; do sed -i 's/new StringWriter()/new EscritorSincronizado()/' $f; grep -c "using TutorFlow.Api.Tests.Dobles" $f; done; cd ../..; dotnet build -warnaserror -v q 2>&1 | grep -E "error|Errores" | head

